import { Component, createContext, createEffect, createSignal, JSX, mergeProps, useContext } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { spacing } from "#core/ui-next/utilities/spacing.js";

function getDefaultColor(opacity: number) {
	return `rgba(77, 83, 102, ${opacity})`;
}

function getDefaultGradient(angle: number) {
	return `linear-gradient(${angle}deg, ${getDefaultColor(0.7)} 0%, ${getDefaultColor(0)} 100%)`;
}

interface DividerContext {
	isHorizontal: boolean;
}

const DividerContext = createContext<DividerContext>();

export interface DividerProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/** The width of the line in its cross axis, perpendicular to the length */
	crossWidth?: spacing;
	length?: spacing;
	margin?: number;
	useGradient?: boolean;
	gradientOverride?: string;
	color?: string;
}

const DividerComponent: Component<DividerProps> = (props) => {
	const ctx = useContext(DividerContext);

	const defaults: DividerProps = { crossWidth: "0\\.5", length: "full", margin: 0, useGradient: false };
	const mergedProps = mergeProps(defaults, props);

	const [margin, setMargin] = createSignal<string>("");
	const [height, setHeight] = createSignal<string>("");
	const [width, setWidth] = createSignal<string>("");

	if (!ctx) {
		throw new Error("Divider must be used within a <DividerContext.Provider>");
	}

	createEffect(() => {
		setMargin(ctx.isHorizontal ? `my-${mergedProps.margin}` : `mx-${mergedProps.margin}`);
		setHeight(`h-${ctx.isHorizontal ? mergedProps.crossWidth : mergedProps.length}`);
		setWidth(`w-${ctx.isHorizontal ? mergedProps.length : mergedProps.crossWidth}`);
	});

	return (
		<div
			{...props}
			class={`${height()} ${width()} ${margin()} ${props.class ?? ""}`}
			style={{
				background: mergedProps.useGradient
					? (props.gradientOverride ?? getDefaultGradient(ctx.isHorizontal ? 90 : 0))
					: (props.color ?? getDefaultColor(0.7)),
			}}
		/>
	);
};

const HorizontalDividerComponent: Component<DividerProps> = (props) => {
	return (
		<DividerContext.Provider value={{ isHorizontal: true }}>
			<DividerComponent {...props} />
		</DividerContext.Provider>
	);
};

const VerticalDividerComponent: Component<DividerProps> = (props) => {
	return (
		<DividerContext.Provider value={{ isHorizontal: false }}>
			<DividerComponent {...props} />
		</DividerContext.Provider>
	);
};

export const Divider = {
	Horizontal: ComponentRegistry.register({
		name: "Divider.Horizontal",
		createInstance: HorizontalDividerComponent,
	}),
	Vertical: ComponentRegistry.register({
		name: "Divider.Vertical",
		createInstance: VerticalDividerComponent,
	}),
};
